#!/usr/bin/env python3
"""Strip JavaScript from HTML in place, retaining untouched source verbatim."""
import html
import re
import sys
from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import unquote

URL_ATTRS = frozenset('href src action formaction xlink:href data poster background cite manifest codebase archive longdesc usemap profile'.split())
DROP_CONTENT = frozenset({'script', 'applet', 'object', 'embed'})
BAD_CSS = re.compile(r'expression\s*\(|behavior\s*:|-moz-binding\s*:|@import\b|url\s*\(\s*[\"\']?\s*(?:javascript|vbscript|data\s*:\s*text/html)\s*:', re.I)


def unsafe_url(value):
    value = html.unescape(str(value))
    for _ in range(4):
        decoded = unquote(value)
        if decoded == value:
            break
        value = decoded
    value = re.sub(r'[\x00-\x20\x7f]+', '', value).casefold()
    if value.startswith(('javascript:', 'vbscript:', 'data:text/html')):
        return True
    return value.startswith('data:') and not value.startswith(('data:image/', 'data:audio/', 'data:video/', 'data:font/'))


class TagParser(HTMLParser):
    def __init__(self, raw):
        super().__init__(convert_charrefs=False)
        self.raw = raw
        self.result = None

    def handle_starttag(self, tag, attrs):
        self.result = (False, tag, attrs, self.get_starttag_text())

    def handle_startendtag(self, tag, attrs):
        self.result = (False, tag, attrs, self.get_starttag_text())

    def handle_endtag(self, tag):
        self.result = (True, tag, [], self.raw)


def clean_tag(raw):
    parser = TagParser(raw)
    try:
        parser.feed(raw)
    except Exception:
        return raw
    parsed = parser.result
    if not parsed:
        return raw
    closing, tag, attrs, original = parsed
    if closing:
        return raw
    changes = False
    safe = []
    for name, value in attrs:
        key = name.lower()
        if key.startswith('on') or key == 'srcdoc':
            changes = True
            continue
        if value is not None and key in URL_ATTRS and unsafe_url(value):
            changes = True
            continue
        if value is not None and key == 'style':
            clean_value = BAD_CSS.sub('', value)
            if clean_value != value:
                changes = True
                value = clean_value
        safe.append((name, value))
    if not changes:
        return raw
    self_closing = raw.rstrip().endswith('/>')
    result = ['<' + tag]
    for name, value in safe:
        result.append(' ' + name if value is None else ' ' + name + '="' + html.escape(value, quote=True) + '"')
    result.append('/>' if self_closing else '>')
    return ''.join(result)


def tokenize(source):
    """Yield HTML tokens and intervening text; quoted '>' does not end a tag."""
    i, n = 0, len(source)
    while i < n:
        start = source.find('<', i)
        if start < 0:
            yield source[i:], False
            return
        if start > i:
            yield source[i:start], False
        if source.startswith('<!--', start):
            end = source.find('-->', start + 4)
            end = n if end < 0 else end + 3
        else:
            quote = None
            end = start + 1
            while end < n:
                ch = source[end]
                if quote:
                    if ch == quote:
                        quote = None
                elif ch in '\"\'':
                    quote = ch
                elif ch == '>':
                    end += 1
                    break
                end += 1
        yield source[start:end], True
        i = end


def sanitize(source):
    out = []
    suppressed = []
    raw_text = None
    for token, is_tag in tokenize(source):
        if not is_tag:
            if not suppressed:
                out.append(token)
            continue
        if token.startswith('<!--') or token.startswith('<!') or token.startswith('<?'):
            if not suppressed:
                out.append(token)
            continue
        parser = TagParser(token)
        try:
            parser.feed(token)
        except Exception:
            if not suppressed:
                out.append(token)
            continue
        parsed = parser.result
        if not parsed:
            if not suppressed:
                out.append(token)
            continue
        closing, tag, attrs, _ = parsed
        tag = tag.lower()
        if raw_text:
            if closing and tag == raw_text:
                if not suppressed:
                    out.append(token)
                raw_text = None
            elif not suppressed:
                out.append(token)
            continue
        if suppressed:
            if closing and tag == suppressed[-1]:
                suppressed.pop()
            elif not closing and tag in DROP_CONTENT and tag not in {'embed'}:
                suppressed.append(tag)
            continue
        if not closing and tag in DROP_CONTENT:
            if tag != 'embed' and not token.rstrip().endswith('/>'):
                suppressed.append(tag)
            continue
        # Sanitize srcdoc recursively, retaining safe embedded markup.
        if not closing and any(name.lower() == 'srcdoc' for name, _ in attrs):
            for name, value in attrs:
                if name.lower() == 'srcdoc' and value is not None:
                    embedded = html.escape(sanitize(html.unescape(value)), quote=True)
                    token = re.sub(r'(?i)(\s+srcdoc\s*=\s*)("[^"]*"|\'[^\']*\'|[^\s>]+)', lambda m: m.group(1) + '"' + embedded + '"', token, count=1)
                    break
        out.append(clean_tag(token))
        if not closing and tag in {'textarea', 'title', 'style', 'xmp', 'noembed', 'noframes'}:
            raw_text = tag
    return ''.join(out)


def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py HTML_FILE', file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    with path.open(encoding='utf-8', errors='surrogateescape', newline='') as f:
        source = f.read()
    with path.open('w', encoding='utf-8', errors='surrogateescape', newline='') as f:
        f.write(sanitize(source))
    return 0


if __name__ == '__main__':
    sys.exit(main())
